import React from "react";
import { BorderBeam } from "./BorderBeam";

const AnimatedButton = React.forwardRef(
  ({ children, onClick, className = "", variant = "primary" }, ref) => {
    const baseStyles =
      "relative px-8 py-4 rounded-full font-semibold text-lg overflow-hidden group transition-all duration-300";

    const variantStyles = {
      primary:
        "bg-black text-white shadow-[0_8px_20px_rgba(0,0,0,0.15)] hover:shadow-[0_12px_25px_rgba(0,0,0,0.25)]",
      secondary:
        "bg-white/60 border border-white/40 text-black backdrop-blur-[20px] shadow-[0_10px_30px_rgba(0,0,0,0.05)] hover:shadow-md hover:bg-white/80",
      animated:
        "bg-transparent text-black border-2 border-transparent relative overflow-hidden",
    };

    if (variant === "animated") {
      return (
        <div className="relative inline-block">
          <button
            ref={ref}
            onClick={onClick}
            className={`${baseStyles} ${variantStyles[variant]} bg-black text-white`}
          >
            <span className="relative z-10 flex items-center justify-center gap-2">
              {children}
            </span>

            {/* Animated hover glow */}
            <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white to-transparent opacity-0 group-hover:opacity-20 transition-opacity duration-300" />
          </button>

          {/* Border Beam Animation */}
          <BorderBeam
            duration={3}
            delay={0}
            borderWidth={2}
            className="absolute inset-0 rounded-full pointer-events-none"
          />
          <BorderBeam
            duration={3}
            delay={1.5}
            borderWidth={2}
            className="absolute inset-0 rounded-full pointer-events-none"
          />
        </div>
      );
    }

    return (
      <button
        ref={ref}
        onClick={onClick}
        className={`${baseStyles} ${variantStyles[variant]}`}
      >
        <span className="relative z-10 flex items-center justify-center gap-2">
          {children}
        </span>
      </button>
    );
  }
);

AnimatedButton.displayName = "AnimatedButton";

export { AnimatedButton };
